'use server';

import { revalidatePath } from 'next/cache';

// In-memory storage for demonstration purposes
// In a real app, this would be a database
const notificationPreferences = new Map<string, boolean>();

export async function toggleNotificationPreference(userId: string) {
  // Get current preference (default to false if not set)
  const currentPreference = notificationPreferences.get(userId) ?? false;

  // Toggle the preference
  const newPreference = !currentPreference;
  notificationPreferences.set(userId, newPreference);

  // Refresh the current page to show updated preference
  // This is Next.js's recommended approach for refreshing without redirecting
  revalidatePath('/');

  return newPreference;
}

export async function getNotificationPreference(userId: string): Promise<boolean> {
  return notificationPreferences.get(userId) ?? false;
}

