import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  // For demo purposes, using a hardcoded user ID
  const userId = 'user-123';
  const notificationsEnabled = await getNotificationPreference(userId);

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Settings</h1>
      <div style={{ marginTop: '2rem' }}>
        <h2>Notification Preferences</h2>
        <form action={toggleNotificationPreference.bind(null, userId)}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginTop: '1rem' }}>
            <label htmlFor="notifications" style={{ fontSize: '1rem' }}>
              Notifications: <strong>{notificationsEnabled ? 'ON' : 'OFF'}</strong>
            </label>
            <button
              type="submit"
              style={{
                padding: '0.5rem 1rem',
                backgroundColor: notificationsEnabled ? '#dc2626' : '#16a34a',
                color: 'white',
                border: 'none',
                borderRadius: '0.375rem',
                cursor: 'pointer',
                fontSize: '1rem'
              }}
            >
              Turn {notificationsEnabled ? 'OFF' : 'ON'}
            </button>
          </div>
        </form>
        <p style={{ marginTop: '1rem', color: '#666', fontSize: '0.875rem' }}>
          Click the button to toggle. The page will refresh automatically to show the updated preference.
        </p>
      </div>
    </main>
  );
}

